import java.math.BigDecimal;
import org.springframework.web.client.RestClient;

public final class HttpExchangeRateGateway implements ExchangeRateGateway {
    private record RateResponse(BigDecimal rate) {}

    private final RestClient client;

    public HttpExchangeRateGateway(RestClient client) {
        this.client = client;
    }

    @Override
    public BigDecimal rateToEur(String currency) {
        RateResponse response = client.get().uri("/rates/{currency}", currency.toUpperCase())
                .retrieve().body(RateResponse.class);
