package $G.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;

public final class Claim {
    static final BigDecimal APPROVAL_THRESHOLD_EUR = new BigDecimal("1000");

    private final ClaimId id;
    private final EmployeeId employeeId;
    private final BigDecimal amount;
    private final String currency;
    private final BigDecimal amountInEur;
    private final ClaimStatus status;

    private Claim(ClaimId id, EmployeeId employeeId, BigDecimal amount, String currency,
                  BigDecimal amountInEur, ClaimStatus status) {
        this.id = id;
        this.employeeId = employeeId;
        this.amount = amount;
        this.currency = currency;
        this.amountInEur = amountInEur;
        this.status = status;
    }

    public static Claim submit(ClaimId id, EmployeeId employeeId, BigDecimal amount, String currency,
                               BigDecimal rateToEur) {
        if (id == null || employeeId == null) throw new IllegalArgumentException("ids are required");
        if (amount == null || amount.signum() <= 0) throw new IllegalArgumentException("amount must be positive");
        if (currency == null || currency.isBlank()) throw new IllegalArgumentException("currency is required");
        if (rateToEur == null || rateToEur.signum() <= 0) throw new IllegalArgumentException("rate must be positive");
        BigDecimal eur = amount.multiply(rateToEur).setScale(2, RoundingMode.HALF_UP);
        ClaimStatus status = eur.compareTo(APPROVAL_THRESHOLD_EUR) > 0
                ? ClaimStatus.PENDING_APPROVAL : ClaimStatus.APPROVED;
        return new Claim(id, employeeId, amount, currency.toUpperCase(), eur, status);
    }

    public ClaimId id() { return id; }
    public EmployeeId employeeId() { return employeeId; }
    public BigDecimal amount() { return amount; }
    public String currency() { return currency; }
    public BigDecimal amountInEur() { return amountInEur; }
    public ClaimStatus status() { return status; }
}
