import org.springframework.beans.factory.annotation.Value;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.web.client.RestClient;

@Configuration
class ClaimConfiguration {
    @Bean
    ClaimRepository claimRepository() {
        return new InMemoryClaimRepository();
    }

    @Bean
    ExchangeRateGateway exchangeRateGateway(@Value("\${exchange-rates.base-url}") String baseUrl) {
        return new HttpExchangeRateGateway(RestClient.builder().baseUrl(baseUrl).build());
    }

    @Bean
    SubmitClaim submitClaim(ClaimRepository claims, ExchangeRateGateway rates) {
        return new SubmitClaim(claims, rates);
    }
}
